-- Migration 0065_source_registry: generated by drizzle-kit (enums, table, checks, key), grants and backfill hand-written, reviewed before commit.
-- Reviewed-by: Claude (agent, #478)
-- The source registry (#478, D-048): one global table (GLOBAL_TABLES, no RLS) that decides whether,
-- how and how often CauseDeck may read an external source. Staff manage it through the app role
-- (SELECT, INSERT, UPDATE; no DELETE), like access_mode_registry (0012); the clerk role has no
-- privileges on it. source_no_captcha_chk keeps court and notice sources off the captcha tier.
-- Additive only: access_mode_registry and its rows are untouched and keep driving court adapters.
-- Backfill: one 'court' source per distinct access_mode_registry.adapter_id, fail closed (terms and
-- counsel pending, cleared_at null), access mode from the strongest enabled row. Staff fill in the
-- real base URL and owner, then clear it once counsel (#118) has.
CREATE TYPE "public"."source_access_mode" AS ENUM('A0', 'A1', 'A2', 'A3');--> statement-breakpoint
CREATE TYPE "public"."source_kind" AS ENUM('court', 'notice', 'news', 'licensed', 'corpus');--> statement-breakpoint
CREATE TYPE "public"."source_max_tier" AS ENUM('http', 'headless', 'proxy', 'captcha');--> statement-breakpoint
CREATE TYPE "public"."source_review_status" AS ENUM('pending', 'cleared', 'rejected');--> statement-breakpoint
CREATE TABLE "source" (
	"id" text PRIMARY KEY NOT NULL,
	"kind" "source_kind" NOT NULL,
	"base_url" text NOT NULL,
	"owner" text NOT NULL,
	"access_mode" "source_access_mode" DEFAULT 'A0' NOT NULL,
	"terms_status" "source_review_status" DEFAULT 'pending' NOT NULL,
	"counsel_status" "source_review_status" DEFAULT 'pending' NOT NULL,
	"cleared_at" timestamp with time zone,
	"rate_limit_per_minute" integer DEFAULT 1 NOT NULL,
	"retention_days" integer DEFAULT 30 NOT NULL,
	"residency" text DEFAULT 'in' NOT NULL,
	"max_tier" "source_max_tier" DEFAULT 'http' NOT NULL,
	"max_cost_dollars" numeric(10, 4) DEFAULT '0' NOT NULL,
	"kill_switch" boolean DEFAULT false NOT NULL,
	"notes" text,
	"updated_by" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "source_no_captcha_chk" CHECK (not ("source"."kind" in ('court', 'notice') and "source"."max_tier" = 'captcha')),
	CONSTRAINT "source_rate_limit_chk" CHECK ("source"."rate_limit_per_minute" > 0),
	CONSTRAINT "source_retention_chk" CHECK ("source"."retention_days" >= 0),
	CONSTRAINT "source_max_cost_chk" CHECK ("source"."max_cost_dollars" >= 0),
	CONSTRAINT "source_cleared_chk" CHECK ("source"."cleared_at" is null or ("source"."terms_status" = 'cleared' and "source"."counsel_status" = 'cleared'))
);
--> statement-breakpoint
ALTER TABLE "source" ADD CONSTRAINT "source_updated_by_user_id_fk" FOREIGN KEY ("updated_by") REFERENCES "public"."user"("id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
REVOKE ALL ON "source" FROM PUBLIC, causedeck_app, causedeck_clerk;--> statement-breakpoint
GRANT SELECT, INSERT, UPDATE ON "source" TO causedeck_app;--> statement-breakpoint
INSERT INTO "source" ("id", "kind", "base_url", "owner", "access_mode", "notes")
SELECT
  "adapter_id",
  'court',
  'urn:causedeck:adapter:' || "adapter_id",
  'unassigned',
  CASE max(CASE WHEN "enabled" THEN CASE "mode" WHEN 'user_supplied' THEN 0 WHEN 'device_user_triggered' THEN 1 WHEN 'official' THEN 2 WHEN 'licensed' THEN 2 ELSE 0 END ELSE 0 END)
    WHEN 0 THEN 'A0'::"source_access_mode"
    WHEN 1 THEN 'A1'::"source_access_mode"
    ELSE 'A2'::"source_access_mode"
  END,
  max("counsel_note")
FROM "access_mode_registry"
GROUP BY "adapter_id"
ON CONFLICT ("id") DO NOTHING;
